"""Seller-facing API: read a business description, review/edit the profile, list orders."""

import json
import re
from pathlib import Path
from typing import Annotated

from fastapi import APIRouter, Depends, File, Form, HTTPException, UploadFile
from pydantic import BaseModel
from sqlmodel import Session, select

from app import audit
from app.agents.claude_client import Claude, ClaudeBudgetExceeded, make_claude_client
from app.agents.reader import MAX_IMAGE_BYTES, Profile, ReaderError, read_business
from app.config import Settings, get_settings
from app.db import get_engine, get_session
from app.models import Business, Order
from app.sites.hosts import RESERVED_SUBDOMAINS, SUBDOMAIN, site_url

router = APIRouter(prefix="/api", tags=["businesses"])
SELLERS = Path(__file__).resolve().parents[2] / "tests" / "fixtures" / "sellers"


def get_claude(settings: Annotated[Settings, Depends(get_settings)]) -> Claude:
    """FastAPI dependency. Tests override this."""
    return make_claude_client(settings, get_engine() if settings.claude_mode == "live" else None)


def slugify(name: str) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", name.lower().replace("'", "")).strip("-")
    return s[:30].strip("-") or "shop"


def unique_subdomain(session: Session, base: str) -> str:
    candidate, n = base, 2
    while candidate in RESERVED_SUBDOMAINS or session.exec(select(Business.id).where(Business.subdomain == candidate)).first():
        candidate, n = f"{base[:27]}-{n}", n + 1
    return candidate


def business_out(b: Business, settings: Settings) -> dict:
    return {
        "id": b.id,
        "subdomain": b.subdomain,
        "site_url": site_url(b.subdomain, settings) if b.subdomain else None,
        "status": b.status,
        "profile": json.loads(b.profile_json),
    }


def get_business(session: Session, business_id: int) -> Business:
    b = session.get(Business, business_id)
    if b is None:
        raise HTTPException(status_code=404, detail="We couldn't find that business.")
    return b


@router.get("/samples")
def samples() -> list[dict]:
    """The three sample seller inputs, so the 'Try an example' buttons can fill the form."""
    out = []
    for path in sorted(SELLERS.glob("*.json")):
        d = json.loads(path.read_text(encoding="utf-8"))
        out.append({"id": d["id"], "owner_name": d["owner_name"], "city": d["city"],
                    "description": d["description"], "price_list": d["price_list"]})
    return out


@router.post("/businesses", status_code=201)
async def create_business(
    settings: Annotated[Settings, Depends(get_settings)],
    session: Annotated[Session, Depends(get_session)],
    claude: Annotated[Claude, Depends(get_claude)],
    description: Annotated[str, Form(max_length=4000)] = "",
    price_list: Annotated[str, Form(max_length=4000)] = "",
    photo: Annotated[UploadFile | None, File()] = None,
) -> dict:
    image = None
    if photo is not None and photo.filename:
        data = await photo.read(MAX_IMAGE_BYTES + 1)
        image = (data, (photo.content_type or "").lower())
    try:
        profile = read_business(claude, description=description, price_list=price_list, image=image)
    except ReaderError as e:
        audit.record(session, actor="reader", action="read_business", result="failed", detail=str(e)[:300])
        raise HTTPException(status_code=422, detail=str(e)) from e
    except ClaudeBudgetExceeded as e:
        audit.record(session, actor="reader", action="read_business", result="blocked", detail=str(e))
        raise HTTPException(status_code=503, detail="Our assistant has reached today's limit. Please try again tomorrow.") from e

    b = Business(name=profile.name, description=description, price_list_text=price_list,
                 profile_json=profile.model_dump_json(), subdomain=unique_subdomain(session, slugify(profile.name)))
    session.add(b)
    session.commit()
    session.refresh(b)
    audit.record(session, actor="reader", action="read_business", target=f"business:{b.id}", result="ok",
                 business_id=b.id, detail=f"{len(profile.products)} products" + (", with photo" if image else ""))
    return business_out(b, settings)


@router.get("/businesses")
def list_businesses(settings: Annotated[Settings, Depends(get_settings)],
                    session: Annotated[Session, Depends(get_session)]) -> list[dict]:
    rows = session.exec(select(Business).order_by(Business.id.desc())).all()
    return [{"id": b.id, "name": b.name, "subdomain": b.subdomain,
             "site_url": site_url(b.subdomain, settings) if b.subdomain else None} for b in rows]


@router.get("/businesses/{business_id}")
def read_one(business_id: int, settings: Annotated[Settings, Depends(get_settings)],
             session: Annotated[Session, Depends(get_session)]) -> dict:
    return business_out(get_business(session, business_id), settings)


class ProfileUpdate(BaseModel):
    profile: Profile
    subdomain: str


@router.put("/businesses/{business_id}")
def update_business(business_id: int, body: ProfileUpdate, settings: Annotated[Settings, Depends(get_settings)],
                    session: Annotated[Session, Depends(get_session)]) -> dict:
    b = get_business(session, business_id)
    sub = body.subdomain.strip().lower()
    if not SUBDOMAIN.match(sub):
        raise HTTPException(status_code=422, detail="Site address can use only letters, numbers and dashes (2–42 characters).")
    if sub in RESERVED_SUBDOMAINS:
        raise HTTPException(status_code=422, detail="That site address is reserved. Please pick another.")
    taken = session.exec(select(Business.id).where(Business.subdomain == sub, Business.id != b.id)).first()
    if taken:
        raise HTTPException(status_code=409, detail="That site address is already taken. Please pick another.")
    old_sub = b.subdomain
    b.name = body.profile.name
    b.profile_json = body.profile.model_dump_json()
    b.subdomain = sub
    session.add(b)
    session.commit()
    session.refresh(b)
    audit.record(session, actor="owner", action="profile_saved", target=f"business:{b.id}", result="ok",
                 business_id=b.id, detail=f"subdomain {old_sub} -> {sub}" if old_sub != sub else "")
    return business_out(b, settings)


@router.get("/businesses/{business_id}/orders")
def list_orders(business_id: int, session: Annotated[Session, Depends(get_session)]) -> list[dict]:
    get_business(session, business_id)
    rows = session.exec(select(Order).where(Order.business_id == business_id).order_by(Order.id.desc())).all()
    return [{"id": o.id, "customer_name": o.customer_name, "customer_phone": o.customer_phone,
             "items": json.loads(o.items_json), "total_inr": o.total_inr, "note": o.note,
             "email_status": o.email_status, "created_at": o.created_at.replace(tzinfo=None).isoformat() + "Z"} for o in rows]
"""FastAPI app: API routers, internal endpoints, seller sites and the built frontend.

Requests whose Host is a seller site (`<subdomain>.APP_DOMAIN` or a seller's
own domain in the DB) get that seller's pages; everything else gets the app.
"""

from contextlib import asynccontextmanager
from pathlib import Path

from typing import Annotated

from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import FileResponse, PlainTextResponse
from fastapi.staticfiles import StaticFiles

from sqlmodel import Session

from app.config import REPO_ROOT, Settings, get_settings
from app.db import get_session, init_db
from app.routers import businesses, health, internal, launch
from app.sites import routes as seller_routes

FRONTEND_DIST = REPO_ROOT / "frontend" / "dist"


@asynccontextmanager
async def lifespan(_app: FastAPI):
    init_db()
    yield


def create_app(*, frontend_dist: Path = FRONTEND_DIST, run_lifespan: bool = True) -> FastAPI:
    app = FastAPI(title="LaunchWitness", lifespan=lifespan if run_lifespan else None)
    app.include_router(health.router)
    app.include_router(internal.router)
    app.include_router(businesses.router)
    app.include_router(launch.router)
    app.include_router(seller_routes.router)

    assets = frontend_dist / "assets"
    if assets.is_dir():
        app.mount("/assets", StaticFiles(directory=assets), name="assets")

    @app.get("/{path:path}", include_in_schema=False)
    def frontend(
        path: str,
        request: Request,
        settings: Annotated[Settings, Depends(get_settings)],
        session: Annotated[Session, Depends(get_session)],
    ):
        if path.startswith(("api/", "internal/")):
            raise HTTPException(status_code=404)
        page = seller_routes.seller_page(path, request, settings, session)
        if page is not None:
            return page
        index = frontend_dist / "index.html"
        if not index.is_file():
            return PlainTextResponse("Frontend not built. Run: cd frontend && npm run build")
        return FileResponse(index)

    return app


app = create_app()
"""Shared test fixtures.

- Settings are built from defaults only (no `.env`, no real env vars).
- The DB is an in-memory SQLite.
- Any network connection to a non-local address fails the test (`no_network`, autouse).
"""

import socket
from collections.abc import Iterator

import pytest
from fastapi.testclient import TestClient
from sqlalchemy.engine import Engine
from sqlmodel import Session

from app.agents.claude_client import FixtureClaudeClient
from app.config import Settings, get_settings
from app.integrations import Integrations, fake_integrations, get_integrations
from app.mail.smtp import FakeMailer, get_mailer
from app.routers.businesses import get_claude
from app.db import get_session, init_db, make_engine
from app.main import create_app

_LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1", "testserver"}


class NetworkBlocked(RuntimeError):
    pass


def _host_of(address) -> str | None:
    if isinstance(address, tuple) and address:
        return str(address[0])
    return None  # unix sockets etc.


@pytest.fixture(autouse=True)
def no_network(monkeypatch) -> list[str]:
    """Block (and record) every non-local connection. Returns the list of blocked hosts."""
    blocked: list[str] = []

    # A local proxy would turn a "localhost" connection into a real outbound one.
    for var in ("HTTP_PROXY", "HTTPS_PROXY", "ALL_PROXY", "http_proxy", "https_proxy", "all_proxy"):
        monkeypatch.delenv(var, raising=False)
    real_connect = socket.socket.connect
    real_connect_ex = socket.socket.connect_ex
    real_getaddrinfo = socket.getaddrinfo

    def guard(host):
        if host is not None and host not in _LOCAL_HOSTS:
            blocked.append(host)
            raise NetworkBlocked(f"Real network call attempted in a test: {host}")

    def connect(self, address):
        guard(_host_of(address))
        return real_connect(self, address)

    def connect_ex(self, address):
        guard(_host_of(address))
        return real_connect_ex(self, address)

    def getaddrinfo(host, *args, **kwargs):
        guard(host if isinstance(host, str) else None)
        return real_getaddrinfo(host, *args, **kwargs)

    real_sendto = socket.socket.sendto

    def sendto(self, data, *args):
        guard(_host_of(args[-1]) if args else None)  # UDP (e.g. DNS queries)
        return real_sendto(self, data, *args)

    monkeypatch.setattr(socket.socket, "connect", connect)
    monkeypatch.setattr(socket.socket, "sendto", sendto)
    monkeypatch.setattr(socket.socket, "connect_ex", connect_ex)
    monkeypatch.setattr(socket, "getaddrinfo", getaddrinfo)
    return blocked


@pytest.fixture
def clean_env(monkeypatch):
    """Remove any real env vars that map to Settings fields."""
    for name in Settings.model_fields:
        monkeypatch.delenv(name.upper(), raising=False)


@pytest.fixture
def make_settings(clean_env):
    def _make(**overrides) -> Settings:
        overrides.setdefault("database_url", "sqlite://")
        return Settings(_env_file=None, **overrides)

    return _make


@pytest.fixture
def settings(make_settings) -> Settings:
    return make_settings()


@pytest.fixture
def engine(settings) -> Engine:
    eng = make_engine(settings.database_url)
    init_db(eng)
    return eng


@pytest.fixture
def session(engine) -> Iterator[Session]:
    with Session(engine) as s:
        yield s


@pytest.fixture
def mailer() -> FakeMailer:
    return FakeMailer()


@pytest.fixture
def claude() -> FixtureClaudeClient:
    return FixtureClaudeClient()


@pytest.fixture
def integ(settings) -> Integrations:
    """A fresh fake world (GoDaddy, availability, mailbox, DNS, HTTP) with no real sleeping."""
    return fake_integrations(settings)


@pytest.fixture
def client(settings, engine, mailer, claude, integ) -> Iterator[TestClient]:
    app = create_app(run_lifespan=False)

    def _session():
        with Session(engine) as s:
            yield s

    app.dependency_overrides[get_settings] = lambda: settings
    app.dependency_overrides[get_session] = _session
    app.dependency_overrides[get_mailer] = lambda: mailer
    app.dependency_overrides[get_claude] = lambda: claude
    app.dependency_overrides[get_integrations] = lambda: integ
    with TestClient(app) as c:
        yield c
"""M4 (code-only parts, fakes): Checker, playbook, Doctor — incl. refuse-outside-playbook."""

import json
from pathlib import Path

import pytest
from sqlmodel import Session, select

from app.agents.checker import checks_for, run_all, run_check
from app.agents.claude_client import FixtureClaudeClient
from app.agents.doctor import MAX_ATTEMPTS, DoctorRefused, diagnose, repair
from app.agents.executor import Ctx
from app.agents.playbook import FIXES_FOR, PLAYBOOK, apply_fix
from app.models import AuditEvent, Business, CheckResult, Order, Plan
from tests.test_m3_launch import approve, meera, plan

FIXTURES = Path(__file__).parent / "fixtures" / "claude"
DOMAIN = "meerascakes.in"


class ScriptedDoctor:
    def __init__(self, *replies):
        self.replies, self.calls = list(replies), []

    def ask_json(self, **kw):
        self.calls.append(kw)
        return self.replies.pop(0) if len(self.replies) > 1 else self.replies[0]


def launched(client, integ, mode="full") -> int:
    if mode == "full":
        integ.godaddy.owned.add(DOMAIN)
        integ.godaddy.zones[DOMAIN] = [{"type": "TXT", "name": "@", "data": "keep-me"}]
        p = approve(client, plan(client, meera(client), "full", DOMAIN))
    else:
        p = approve(client, plan(client, meera(client)))
    assert p["status"] == "done", p["steps"]
    return p["id"]


def ctx_for(engine, settings, integ, plan_id):
    s = Session(engine)
    pl = s.get(Plan, plan_id)
    return Ctx(s, settings, integ, pl, s.get(Business, pl.business_id))


def drop(integ, rtype, name):
    integ.godaddy.zones[DOMAIN] = [r for r in integ.godaddy.zones[DOMAIN] if not (r["type"] == rtype and r["name"] == name)]


# ---------- Checker ----------

def test_full_launch_all_checks_green(client, integ, engine, settings):
    ctx = ctx_for(engine, settings, integ, launched(client, integ))
    outs = run_all(ctx)
    assert [o.check for o in outs] == ["site_points", "https", "email_mx", "email_spf", "email_dkim", "email_dmarc",
                                       "test_order", "launch_clean"]
    assert all(o.passed for o in outs), [(o.check, o.detail) for o in outs]
    assert len(ctx.session.exec(select(CheckResult)).all()) == 8
    test_order = ctx.session.exec(select(Order).where(Order.is_test)).one()
    assert integ.inbox.find(subject_contains=f"(#{test_order.id})")[0].subject.startswith("[TEST] New order")


def test_sandbox_runs_site_checks_only(client, integ, engine, settings):
    ctx = ctx_for(engine, settings, integ, launched(client, integ, "sandbox"))
    assert checks_for(ctx) == ["site_points", "https", "test_order", "launch_clean"]
    assert all(o.passed for o in run_all(ctx))


@pytest.mark.parametrize("breakage,check", [
    (lambda i: drop(i, "MX", "@"), "email_mx"),
    (lambda i: drop(i, "TXT", "_dmarc"), "email_dmarc"),
    (lambda i: drop(i, "TXT", "titan1._domainkey"), "email_dkim"),
    (lambda i: drop(i, "A", "@"), "site_points"),
    (lambda i: i.http.broken_cert.add(DOMAIN), "https"),
    (lambda i: setattr(i.mailer, "drop", True), "test_order"),
])
def test_each_check_detects_its_failure(client, integ, engine, settings, breakage, check):
    ctx = ctx_for(engine, settings, integ, launched(client, integ))
    breakage(integ)

