                    : `We tried ${r.attempts.length} time${r.attempts.length === 1 ? "" : "s"} and stopped, so nothing else changes without you.`}
                </p>
                <details>
                  <summary>Details</summary>
                  <ol className="tech">
                    {r.attempts.map((a, i) => (
                      <li key={i}>
