                  <strong>{e.actor}</strong> {e.action} {e.target} → <em>{e.result}</em>
                  {e.detail && <div className="muted">{e.detail}</div>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </details>

      <p>
        <a href={`#/b/${businessId}`}>← Back to your details</a>
      </p>
    </>
  );
}

